const ORG = { '@id': `${SITE}/#organization` };
const ld = data => `<script type="application/ld+json">${JSON.stringify(data).replace(/</g,'\\u003c')}</script>`;
const crumbNames = { 'about.html':'About Us', 'services.html':'Services', 'packages.html':'Packages', 'case-studies.html':'Our Work', 'playground.html':'Playground', 'insights.html':'Articles', 'partner-with-us.html':'Partner With Us', 'contact.html':'Contact Us' };
function pageSchema(page, t, lang) {
  const base = SITE + (lang === 'th' ? '/th/' : '/');
  const out = [];
  if (page.path === 'index.html') out.push({ '@context':'https://schema.org', '@type':'WebSite', '@id':`${SITE}/#website`, url: base, name: studio.name, alternateName: 'JPM Interactive', inLanguage: lang, publisher: ORG });
  if (page.path !== 'index.html' && !page.noindex && !page.draft) {
    const trail = [['Home','index.html']];
    if (page.path.startsWith('case-studies/')) trail.push(['Our Work','case-studies.html']);
    if (page.path.startsWith('insights/')) trail.push(['Articles','insights.html']);
    if (page.article) trail.push([page.topic.name, `insights/${page.topic.slug}.html`]);
    trail.push([page.crumb || crumbNames[page.path] || page.title, page.path]);
    out.push({ '@context':'https://schema.org', '@type':'BreadcrumbList', itemListElement: trail.map(([name,path],i)=>({ '@type':'ListItem', position:i+1, name:t(name), item: base + path })) });
  }
  if (page.path === 'services.html') out.push({ '@context':'https://schema.org', '@type':'ItemList', name: t('Services'), itemListElement: services.map((s,i)=>({ '@type':'ListItem', position:i+1, item:{ '@type':'Service', name:t(s.title), description:t(s.description), url:`${base}services.html#${s.id}`, provider: ORG, areaServed:{ '@type':'Country', name:'Thailand' } } })) });
  if (page.path === 'packages.html') out.push({ '@context':'https://schema.org', '@type':'OfferCatalog', name: t('Packages'), url:`${base}packages.html`, itemListElement: packages.flatMap(pack=>pack.items.map(item=>({ '@type':'Offer', category: t(pack.title), itemOffered:{ '@type':'Service', name:`${t(item.title)} — ${t(pack.title)}`, description:t(item.text), provider: ORG, areaServed:{ '@type':'Country', name:'Thailand' } }, priceSpecification:{ '@type':'PriceSpecification', minPrice:item.startingPrice, priceCurrency:'THB' } }))) });
  if (page.path.startsWith('case-studies/')) { const p = projects.find(x=>`case-studies/${x.slug}.html`===page.path); if (p) out.push({ '@context':'https://schema.org', '@type':'CreativeWork', name:p.title, url:base+page.path, genre:t(p.category), creator: p.employer ? undefined : ORG, inLanguage: lang }); }
  // Articles: Article on each article, CollectionPage on the Articles page and on each indexable topic hub.
  const hubUrl = topic => `${base}insights/${topic.slug}.html`;
  const listOf = list => ({ '@type':'ItemList', itemListElement: list.map((a,i)=>({ '@type':'ListItem', position:i+1, url:`${base}insights/${a.slug}.html`, name:t(a.title) })) });
  if (page.article && !page.draft) { const a = page.article; out.push({ '@context':'https://schema.org', '@type':'Article', '@id':`${base}${page.path}#article`, headline:t(a.title), description:t(a.summary), datePublished:a.published, dateModified:a.updated || a.published, author: ORG, publisher: ORG, inLanguage: lang, mainEntityOfPage: base + page.path, articleSection:t(page.topic.name), genre:t(a.category), image:`${SITE}/${a.cover ? articleImage(a.cover.image).path : 'assets/web/og-cover.jpg'}`, isPartOf:{ '@id':`${hubUrl(page.topic)}#collection` } }); }
  if (page.topic && !page.article && !page.noindex) out.push({ '@context':'https://schema.org', '@type':'CollectionPage', '@id':`${hubUrl(page.topic)}#collection`, url: hubUrl(page.topic), name:t(page.topic.name), description:t(page.topic.intro), inLanguage: lang, isPartOf:{ '@id':`${SITE}/#website` }, publisher: ORG, mainEntity: listOf(articles.filter(a=>a.status==='published' && a.topic===page.topic.slug)) });
  if (page.path === 'insights.html') out.push({ '@context':'https://schema.org', '@type':'CollectionPage', url:`${base}insights.html`, name:t('Articles'), inLanguage: lang, isPartOf:{ '@id':`${SITE}/#website` }, publisher: ORG, hasPart: articleTopics.filter(topic=>articles.some(a=>a.status==='published' && a.topic===topic.slug)).map(topic=>({ '@type':'CollectionPage', name:t(topic.name), url:hubUrl(topic) })), mainEntity: listOf(articles.filter(a=>a.status==='published')) });
  return out.map(ld).join('');
}
