pages.push({ path:'case-studies.html', active:'work', title:'Portfolio: Interactive & Immersive Projects', description:'Portfolio of interactive floors, immersive walls, touchscreen applications, and branded games for brands such as Punthai Coffee, LAZADA, Crowne Plaza, Bangchak, and PTTEP, with original project credits.', body:`${pageHero('OUR WORK · INTERACTIVE & IMMERSIVE PORTFOLIO','Experiences made real.<br><span class="gradient-text">Possibilities made visible.</span>','Project references and videos from our existing portfolio. Explore each experience in its original context.')}<section class="wrap section"><div class="filter-bar requires-js" role="group" aria-label="Filter projects"><button class="filter-button active" data-filter="all" aria-pressed="true">All work</button><button class="filter-button" data-filter="Touchscreen" aria-pressed="false">Touchscreen</button><button class="filter-button" data-filter="Immersive" aria-pressed="false">Interactive & immersive</button></div><p class="filter-count sr-only" role="status"></p><div class="project-grid work-gallery">${projects.map(p=>projectCard(p)).join('')}</div></section>${cta()}` });
for (const project of projects) pages.push({path:`case-studies/${project.slug}.html`,prefix:'../',active:'work', title:`${project.title} — ${project.category} Project`, description:`${project.title}: ${project.category==='Touchscreen'?'a touchscreen application':'an immersive and interactive experience'} in the JPM Media Space portfolio, with project video and original credits.`, body:`${pageHero(`${project.category.toUpperCase()} / PROJECT REFERENCE`,e(project.title),project.employer ? 'Portfolio with Employer — retained attribution from the original website.' : 'From the JPM Media Space project portfolio.')}<section class="wrap project-detail section"><video controls preload="none" poster="${asset(project.image,'../')}" aria-label="${e(project.title)} project video"><source src="${asset(project.video,'../')}" type="video/mp4">Your browser does not support this video. <a href="${asset(project.video,'../')}">Download the project video</a>.</video>${project.story ? `<div class="project-story"><p class="eyebrow">THE EXPERIENCE</p><h2>From a visual story<br><span class="gradient-text">to participation.</span></h2><p>${e(project.story.overview)}</p><div class="project-story-grid project-story-stack"><section><h3>The interaction</h3><p>${e(project.story.interaction)}</p></section><section><h3>The approach</h3><p>${e(project.story.approach)}</p></section></div></div>` : ''}<div class="split${project.story ? ' split-facts-only' : ''}">${project.story ? '' : `<div><p class="eyebrow">THE EXPERIENCE</p><h2>${project.category === 'Touchscreen' ? 'Designed to be explored.' : 'Made for interaction.'}</h2><p>${project.category === 'Touchscreen' ? 'This project appears in the original Touch Screen Program portfolio. Watch the supplied video to explore the application and interaction.' : 'This project appears in the original Interactive & Immersive Experiences portfolio. Watch the supplied video to see the experience in context.'}</p></div>`}<dl class="project-facts"><dt>Discipline</dt><dd>${project.category === 'Touchscreen' ? 'Touchscreen application' : 'Interactive & immersive experience'}</dd><dt>Technology reference</dt><dd>${project.category === 'Touchscreen' ? 'Touchscreen program, as classified in the source portfolio.' : 'Interactive installation. Specific hardware is subject to project confirmation.'}</dd><dt>Credit</dt><dd>${project.employer ? 'Portfolio with Employer. Original employer attribution retained; not represented as a direct JPM Media Space client engagement.' : 'Listed in the JPM Media Space project portfolio.'}</dd></dl></div><a class="text-link" href="../case-studies.html">Back to all work</a></section>${cta('../')}` });
// Playground hero (owner request 2026-10-27): laid out like the Home hero, without a frame. The round mascot reacts to a
// six-key 3D keypad (after a Dribbble 3D keyboard reference); real keys F P D B Z X work too. Logic: playground-hero.js.
const robotKeys = [['feed','F','Feed'],['pet','P','Pet'],['dance','D','Dance'],['boo','B','Boo!'],['sleep','Z','Sleep'],['boom','X','Overload']];
const robotSvg = `<svg class="feed-svg" viewBox="0 0 300 300" role="img" aria-label="A round robot that reacts to the keys"><defs><radialGradient id="feed-body" cx="35%" cy="28%" r="78%"><stop offset="0" stop-color="#ffffff"/><stop offset=".68" stop-color="#ececf4"/><stop offset="1" stop-color="#c3c5d6"/></radialGradient><linearGradient id="feed-rim" x1="0" y1="1" x2="1" y2="0"><stop offset="0" stop-color="#8a63f2"/><stop offset="1" stop-color="#5f86f5"/></linearGradient></defs><ellipse class="feed-shadow" cx="150" cy="272" rx="78" ry="11"/><g class="feed-steam"></g><g class="feed-robot"><circle class="feed-body" r="90" fill="url(#feed-body)"/><g class="feed-visor"><rect x="-68" y="-52" width="136" height="80" rx="38" fill="url(#feed-rim)"/><rect x="-62" y="-46" width="124" height="68" rx="33" fill="#0b0b12"/></g><g class="feed-eyes"></g><g class="feed-cheeks"><ellipse cx="-56" cy="40" rx="12" ry="6"/><ellipse cx="56" cy="40" rx="12" ry="6"/></g><rect class="feed-mouth" x="-16" y="46" width="32" height="8" rx="4"/></g><g class="feed-food"></g><g class="feed-debris"></g><text class="feed-boom" x="150" y="120" text-anchor="middle"></text></svg>`;
const playgroundHero = () => `<section class="hero3d playground-hero" aria-labelledby="playground-title"><div class="wrap hero3d-grid"><div class="hero3d-copy"><h1 id="playground-title"><span class="arcade-chip hero-kicker">${boxIconMarkup}<span class="hero-kicker-text">THE JPM MEDIA SPACE INTERACTIVE PLAYGROUND • PLAYABLE DEMOS</span></span><span class="hero-line">WHICH IDEA FITS YOU?</span> <span class="arcade-highlight hero-line">PLAY IT NOW.</span></h1><p class="arcade-intro">Explore playable creative technology experiments, right in your browser. No downloads or special hardware. Just a little curiosity.</p><div class="button-row">${button('#demo-library','Explore Demos')}${button('contact.html?service=Interactive%20Experience','Build Your Experience',true)}</div></div><div class="robot-stage feed-play requires-js"><div class="robot-glow" aria-hidden="true"></div><div class="feed-stage">${robotSvg}</div><div class="keypad" role="group" aria-label="Robot keys"><div class="keypad-base">${robotKeys.map(([action,key,label])=>`<button type="button" class="keycap${action==='boom'?' keycap-accent':''}" data-robot="${action}" aria-keyshortcuts="${key}" aria-label="${label} (${key})"><span class="keycap-top"><span class="keycap-letter" aria-hidden="true">${key}</span><span class="keycap-label" aria-hidden="true">${label}</span></span></button>`).join('')}</div></div><p class="hero-play-result" role="status">Press a key, or F P D B Z X on your keyboard.</p><p class="feed-count"><span>Robots broken</span> <strong>0</strong> · <a class="hero-play-link" href="contact.html?service=Interactive%20Game">Want a game like this at your booth?</a></p></div></div></section>`;
pages.push({path:'playground.html',active:'playground',title:'Interactive Playground: Try Playable Demos',description:'Try simple browser demos for all six JPM Media Space services: games, touchscreen, immersive spaces, sensors, custom development, and LED or projection.',scripts:['playground.js','service-demos.js','playground-hero.js','playground-player.js'],body:`${playgroundHero()}${serviceDemoNavigation()}${demoLibrary()}<noscript><div class="wrap review-note">These interactive prototypes need JavaScript. You can still explore our services or <a href="contact.html">request a quote</a>.</div></noscript>
<section class="wrap section demo-section" id="catch-game"><div class="demo-description"><p class="eyebrow">EXPERIMENT 001 / CATCH GAME</p><h2>Catch the<br><span class="gradient-text">possibilities.</span></h2><p>A timed catching game for a little friendly competition. Imagine branded objects, a campaign theme, or a product launch challenge.</p><p class="game-rules">Catch the sparks. Avoid the red × objects: they deduct points. Your score stays at zero or above.</p><ul class="clean-list"><li>Mouse / touch: move across the play field.</li><li>Keyboard: focus the field and use ← / → or A / D.</li><li>Mobile: drag or use the on-screen arrow buttons.</li></ul><p class="demo-note">Branding and game settings are configurable. This prototype runs entirely in your browser.</p>${button('contact.html?service=Catch%20Game','Request a game quote',true)}</div><div class="game-shell surface requires-js">${catchSettings()}<div class="game-hud"><span id="game-brand">JPM MEDIA SPACE</span><span>Score <strong id="game-score">0</strong></span><span>Time <strong id="game-time">30</strong>s</span></div><div id="game-view" class="game-view" tabindex="0" role="group" aria-label="Catch Game play field. Use left and right arrows or A and D to move." aria-describedby="game-instructions"><div id="game-objects" aria-hidden="true"></div><span id="game-feedback" class="game-feedback" aria-hidden="true" hidden></span><div id="game-basket" aria-hidden="true"><span></span></div><div class="game-overlay" id="game-overlay"><span class="eyebrow">READY WHEN YOU ARE</span><h3 id="game-overlay-title">Make every<br>catch count.</h3><p id="game-overlay-text">Catch falling sparks. You have 30 seconds.</p><button class="button button-primary" id="game-start"><span class="game-start-label">Start game</span> ${catchPlayIcon}</button></div></div><div class="game-legend" id="game-legend"><span><b class="legend-spark" aria-hidden="true">✦</b> <span>Catch</span> <strong class="legend-points">+10</strong></span><span><b class="legend-hazard" aria-hidden="true">×</b> <span>Avoid</span> <strong class="legend-penalty">−10</strong></span></div><div class="game-controls"><div class="direction-controls"><button id="game-left" aria-label="Move catcher left">←</button><button id="game-right" aria-label="Move catcher right">→</button></div><button class="pill" id="game-pause" disabled>Pause</button><button class="pill" id="game-restart">Restart</button><button class="pill" id="catch-edit" disabled>End round to edit</button></div><p id="game-instructions" class="game-instructions">Drag to move · ← → or A / D to catch · Space to start</p><p id="game-status" class="sr-only" role="status">Game ready.</p></div></section>
${customGameDemo()}${matchingGameDemo()}${luckyWheelDemo()}${quizGameDemo()}<section class="wrap section demo-section" id="scratch-reveal"><div class="demo-description"><p class="eyebrow">EXPERIMENT 002 / SCRATCH REVEAL</p><h2>A little suspense.<br><span class="gradient-text">A bigger reveal.</span></h2><p>Swipe through a soft veil of mist to reveal a moving light scene. A simple concept for brand stories, product reveals, and immersive invitations.</p><p class="demo-note">Drag with a mouse or finger to gently disperse the mist. You can also reveal the scene with a button, or pause the motion.</p>${button('contact.html?service=Scratch%20Reveal','Explore a reveal experience',true)}</div><div class="scratch-shell surface requires-js">${revealSettings()}<div class="scratch-stage" data-color="violet"><div class="scratch-light-scene" aria-hidden="true"><i class="reveal-orb orb-one"></i><i class="reveal-orb orb-two"></i><i class="reveal-ribbon ribbon-one"></i><i class="reveal-ribbon ribbon-two"></i><div class="reveal-sparks"><i style="--n:0"></i><i style="--n:1"></i><i style="--n:2"></i><i style="--n:3"></i><i style="--n:4"></i><i style="--n:5"></i><i style="--n:6"></i><i style="--n:7"></i><i style="--n:8"></i><i style="--n:9"></i><i style="--n:10"></i><i style="--n:11"></i></div></div><div id="reveal-image-backdrop" class="reveal-image-backdrop" aria-hidden="true" hidden></div><img id="reveal-background-image" class="reveal-background-image" alt="Your image behind the mist" hidden><div class="scratch-message"><p id="reveal-brand-preview" hidden></p><h3 class="reveal-brand-message">Players see more of your brand as they move across a wider area.</h3></div><canvas id="scratch-canvas" aria-label="Soft mist reveal. Drag to uncover the moving scene, or use the Reveal scene button."></canvas></div><div class="scratch-controls"><button class="pill" id="scratch-reveal-button">Reveal scene ${bulbIcon}</button><button class="pill" id="scratch-motion" aria-pressed="false">Pause visual</button><button class="pill" id="scratch-reset">Reset</button></div><p id="scratch-status" role="status">Swipe through the mist or reveal the scene.</p></div></section>
${productExplorerDemo()}${additionalServiceDemos()}${cta()}`});
// Articles (2026-10-27): topic hubs at insights/<topic>.html, dated articles with Article structured data.
const published = articles.filter(a=>a.status==='published');
const topicOf = a => articleTopics.find(t=>t.slug===a.topic);
const topicArticles = topic => published.filter(a=>a.topic===topic.slug);
const dateTag = iso => `<time datetime="${iso}">${articleDate(iso)}</time>`;
const articleCard = (a,prefix='') => `<a class="article-card surface reveal" data-article-category="${a.topic}" href="${prefix}insights/${a.slug}.html">${a.cover ? `<span class="article-card-image"><img src="${articleImage(a.cover.image,prefix).src}"${articleImage(a.cover.image).size} alt="" loading="lazy" decoding="async"></span>` : ''}<p class="eyebrow">${topicOf(a).name.toUpperCase()}</p><h3>${a.title}</h3><p>${a.summary}</p><span class="article-meta"><span class="article-meta-info">${dateTag(a.published)}<span aria-hidden="true">·</span><span>${a.readTime} read</span></span><span>Read guide ${externalLinkIcon}</span></span></a>`;
const topicNav = (current='',prefix='') => `<nav class="topic-nav" aria-label="Article topics"><a class="filter-button${current?'':' active'}" href="${prefix}insights.html"${current?'':' aria-current="page"'}>All Articles</a>${articleTopics.map(t=>`<a class="filter-button${current===t.slug?' active':''}" href="${prefix}insights/${t.slug}.html"${current===t.slug?' aria-current="page"':''}>${t.name}</a>`).join('')}</nav>`;
pages.push({path:'insights.html',active:'insights',title:'Articles on Interactive Experience Design',description:'Explore JPM Media Space studio perspectives on interactive experience design, physical spaces, project planning, and creative technology.',body:`${pageHero('','<span class="gradient-text">Articles worth reading</span>','Studio perspectives on interaction, experience, and the spaces in between.')}<section class="wrap section">${topicNav()}<div class="article-grid">${published.map(a=>articleCard(a)).join('')}</div></section><section class="wrap section">${heading('BROWSE BY TOPIC','Browse by topic')}<div class="topic-grid">${articleTopics.map(t=>`<a class="topic-card surface reveal" href="insights/${t.slug}.html"><h3>${t.name}</h3><p>${t.intro}</p><span class="text-link">${topicArticles(t).length ? 'View topic' : 'Coming soon'}</span></a>`).join('')}</div></section>${cta()}`});
for (const topic of articleTopics) {
  const list = topicArticles(topic);
  const related = `<section class="wrap section">${heading('RELATED SERVICES & WORK','See it in practice')}<div class="topic-links">${topic.services.map(id=>{const s=services.find(x=>x.id===id);return `<a class="topic-card surface reveal" href="../services.html#${id}"><h3>${s.title}</h3><p>${s.description}</p><span class="text-link">Explore service</span></a>`;}).join('')}</div><div class="project-grid">${topic.projects.map(slug=>projectCard(projects.find(p=>p.slug===slug),'../')).join('')}</div></section>`;
  pages.push({path:`insights/${topic.slug}.html`,prefix:'../',active:'insights',topic,noindex:!list.length,crumb:topic.name,title:`${topic.name}: Articles and Guides`,description:topic.intro,body:`${pageHero('ARTICLE TOPIC',topic.name,topic.intro)}<section class="wrap section">${topicNav(topic.slug,'../')}${list.length?`<div class="article-grid">${list.map(a=>articleCard(a,'../')).join('')}</div>`:'<div class="topic-empty surface"><p>Articles on this topic are coming soon.</p><p>In the meantime, see how we work on this.</p></div>'}</section>${related}${cta('../')}`});
}
for (const article of articles) {
  const topic = topicOf(article);
  const more = published.filter(a=>a.slug!==article.slug).sort((a,b)=>(b.topic===article.topic)-(a.topic===article.topic)).slice(0,2);
  const cover = article.cover && articleImage(article.cover.image);
  pages.push({path:`insights/${article.slug}.html`,prefix:'../',active:'insights',article,topic,draft:article.status!=='published',ogType:'article',...(cover ? { ogImage:cover.original, ogImageAlt:article.cover.alt, ogImageDims:cover.dims } : {}),title:article.title,description:article.summary,body:`<article class="article-layout wrap"><header class="article-header"><a class="text-link article-back" href="../insights.html" data-article-back aria-label="Back to previous page"><svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="M19 12H5m7 7-7-7 7-7"/></svg><span>Back</span></a><p class="eyebrow"><a href="${topic.slug}.html">${topic.name.toUpperCase()}</a> <span aria-hidden="true">·</span> <span>${article.category.toUpperCase()}</span></p><h1>${article.title}</h1><p class="article-lead">${article.summary}</p><p class="article-byline"><span>JPM Media Space</span><span aria-hidden="true">·</span><span>Published</span> ${dateTag(article.published)}${article.updated&&article.updated!==article.published?`<span aria-hidden="true">·</span><span>Updated</span> ${dateTag(article.updated)}`:''}<span aria-hidden="true">·</span><span>${article.readTime} read</span></p></header>${articleFigure(article.cover,'../',{cover:true})}<div class="article-body">${article.sections.map(([title,text,media],i)=>`<section id="section-${i+1}"><h2>${title}</h2><p>${text}</p>${articleFigure(media,'../')}</section>`).join('')}<p>Explore <a href="../services.html">our services</a>, review <a href="../packages.html">the packages</a>, or <a href="../contact.html">discuss your project</a> with the studio.</p></div></article>${more.length?`<section class="wrap section">${heading('KEEP EXPLORING','Related perspectives',`${topic.slug}.html`,'View topic')}<div class="article-grid">${more.map(a=>articleCard(a,'../')).join('')}</div></section>`:''}${cta('../')}`});
}
pages.push({path:'partner-with-us.html',active:'partner',title:'Partner With Us — B2B Creative Technology',description:'Creative technology partnerships for event agencies, production houses, LED providers, and system integrators. Build interactive experiences with JPM Media Space.',body:`${pageHero('PARTNER WITH US · B2B CREATIVE TECHNOLOGY','Your vision.<br><span class="gradient-text">Our shared ambition.</span>','Bring the brief, the space, or the possibility. We work alongside your team to connect creative ideas with interactive technology.')}<section class="wrap section four-grid">${[['Event Agencies','Interactive games, branded activations, and participatory experiences for your next event.'],['Production Houses','Custom software, visual content, and interactive systems to connect the production.'],['LED Providers','Responsive content and software that bring LED walls, floors, and display environments to life.'],['System Integrators','Connect hardware, sensors, content, and custom applications around the installation.']].map(([title,text],i)=>`<article class="surface reveal"><span class="step-number">0${i+1}</span><h2>${title}</h2><p>${text}</p><a class="text-link" href="contact.html?service=${encodeURIComponent(`Partnership: ${title}`)}">Start a partnership conversation</a></article>`).join('')}</section><section class="wrap split section"><div><p class="eyebrow">A CONNECTED WAY OF WORKING</p><h2>From first idea<br>to final interaction.</h2></div><div><p>Share the audience, project scope, timeline, and available hardware. We can discuss interaction design, custom programs, integration, testing, installation, and support as part of one connected plan.</p><p>Every partnership begins with a conversation about responsibilities, deliverables, and the experience you want to create.</p>${button('contact.html?service=Partnership','Tell us about your project')}</div></section>${cta()}`});
pages.push({path:'contact.html',active:'contact',title:'Contact Us & Request a Quote',description:'Talk to JPM Media Space about an interactive experience, immersive installation, or creative technology project in Thailand. Call, email, LINE, or request a quote.',body:`${pageHero('CONTACT & REQUEST A QUOTE','A possibility begins<br><span class="gradient-text">with a conversation.</span>','Tell us about the experience you have in mind. We’ll explore the idea, the space, and the technology together.')}<section class="wrap section contact-layout"><div><h2>Say hello.</h2><div class="contact-methods"><a href="mailto:${studio.email}"><span>EMAIL</span><span class="contact-method-value">${mailIcon}${studio.email}</span></a><a href="tel:+66962826224"><span>PHONE / K. MAY</span><span class="contact-method-value">${phoneIcon}${studio.phone}</span></a><a href="${studio.line}"><span>LINE</span><span class="contact-method-value">${messageCircleIcon}@jpmmediaspace</span></a></div><img class="line-qr" src="${asset('qr code lineoa.jpg')}" width="150" height="150" alt="QR code for JPM Media Space LINE account" loading="lazy"><p>Prefer a quick conversation? Call K. May or connect with our LINE account.</p></div>${quoteForm()}<noscript><div class="surface"><h2>Share your project brief.</h2><p>Email your idea, audience, venue, and timeline directly to <a href="mailto:jpmmediaspace@gmail.com">jpmmediaspace@gmail.com</a>.</p></div></noscript></section>`});

pages.push({path:'thank-you.html',active:'contact',noindex:true,title:'Thank You — Enquiry Received',description:'Thank you for contacting JPM Media Space about your project.',body:`<section class="wrap section thank-you"><p class="eyebrow">THANK YOU FOR REACHING OUT</p><h1>Your next experience<br><span class="gradient-text">starts here.</span></h1><p>Your enquiry has been submitted. Our team will review your project details and get in touch using the contact information you provided.</p><p>If you need to reach us directly, call <a href="tel:+66962826224">${studio.phone}</a> or message us on <a href="${studio.line}">LINE</a>.</p>${button('case-studies.html','Explore Our Work')}</section>`});

for (const page of pages) {
  await mkdir(new URL(`../${page.path.includes('/') ? page.path.slice(0,page.path.lastIndexOf('/')+1) : ''}`, import.meta.url), {recursive:true});
  const html=layout({...page,prefix:page.prefix||''}).replace('</head>',pageSchema(page,x=>x,'en')+'</head>');
  await writeFile(new URL(`../${page.path}`,import.meta.url),html);
  const thaiPath='th/'+page.path;
  await mkdir(new URL(`../${thaiPath.slice(0,thaiPath.lastIndexOf('/')+1)}`,import.meta.url),{recursive:true});
  let thai=localizeThai(html,page.path);
  // JSON-LD is skipped by the text localizer, so swap in Thai structured data here.
  thai=thai.replace(JSON.stringify(studio.introduction),JSON.stringify(translateThai(studio.introduction)));
  thai=thai.replace(pageSchema(page,x=>x,'en'),pageSchema(page,translateThai,'th'));
  // Game screenshots on the Playground cards have Thai versions.
  thai=thai.replaceAll('assets/playground/','assets/playground/th/');
  if (page.faqs) thai=thai.replace(faqSchema(page.faqs),faqSchema(page.faqs.map(([q,a])=>[translateThai(q),translateThai(a)])));
  await writeFile(new URL(`../${thaiPath}`,import.meta.url),thai);
}
const routes = pages.filter(page=>!page.draft && !page.noindex).map(page=>page.path);
const noindexRoutes = pages.filter(page=>page.noindex).map(page=>page.path);
await writeFile(new URL('../sitemap-plan.json',import.meta.url),JSON.stringify({ note:'Preview only. Set SITE_ORIGIN after release URL approval to emit sitemap.xml and canonical URLs. Draft articles are excluded.', englishRoutes:routes, thaiRoutes:routes.map(route=>'th/'+route), noindexRoutes:[...noindexRoutes,...noindexRoutes.map(route=>'th/'+route)] },null,2)+'\n');
if (process.env.SITE_ORIGIN) {
  const origin=process.env.SITE_ORIGIN.replace(/\/$/,'');
  const today=new Date().toISOString().slice(0,10);
  // Articles and topic hubs report their own update date; other pages use the build date.
  const lastmod=route=>{const page=pages.find(p=>p.path===route);if(page?.article)return page.article.updated||page.article.published;if(page?.topic){const dates=articles.filter(a=>a.status==='published'&&a.topic===page.topic.slug).map(a=>a.updated||a.published).sort();return dates.pop()||today;}return today;};
  const alternates=route=>`<xhtml:link rel="alternate" hreflang="en" href="${e(origin+'/'+route)}"/><xhtml:link rel="alternate" hreflang="th" href="${e(origin+'/th/'+route)}"/><xhtml:link rel="alternate" hreflang="x-default" href="${e(origin+'/'+route)}"/>`;
  await writeFile(new URL('../sitemap.xml',import.meta.url),`<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9" xmlns:xhtml="http://www.w3.org/1999/xhtml">${routes.flatMap(route=>[route,'th/'+route].map(loc=>`<url><loc>${e(origin+'/'+loc)}</loc><lastmod>${lastmod(route)}</lastmod>${alternates(route)}</url>`)).join('')}</urlset>\n`);
  await writeFile(new URL('../robots.txt',import.meta.url),`User-agent: *\nAllow: /\n\nSitemap: ${origin}/sitemap.xml\n`);
  // llms.txt: a plain summary for AI assistants and answer engines (GEO).
  const link=(route,label,note='')=>`- [${label}](${origin}/${route})${note?': '+note:''}`;
  await writeFile(new URL('../llms.txt',import.meta.url),[
    '# JPM Media Space',
    '',
    `> ${studio.name} is a creative technology studio in Thailand that designs interactive games, touchscreen applications, and interactive LED, projection, and sensor content for event booths and brand activations, as well as permanent installations. Also known as JPM Interactive.`,
    '',
    `Contact: ${studio.email} · +66 96 282 6224 · LINE @jpmmediaspace. Languages: Thai and English.`,
    '',
    '## Key pages',
    link('index.html','Home (English)'),link('th/index.html','Home (Thai)'),link('services.html','Services'),link('packages.html','Packages and starting prices'),link('case-studies.html','Our work'),link('playground.html','Playable demos'),link('partner-with-us.html','Partner with us','for event agencies, production houses, LED providers'),link('contact.html','Contact and quotes'),
    '',
    '## Services',
    ...services.map(s=>`- ${s.title}: ${s.description}`),
    '',
    '## FAQ',
    ...faqs.flatMap(([q,a])=>[`### ${q}`,a,'']),
    '## Articles',
    ...articleTopics.flatMap(topic=>{const list=articles.filter(a=>a.status==='published'&&a.topic===topic.slug);return list.length?[`### [${topic.name}](${origin}/insights/${topic.slug}.html)`,topic.intro,...list.map(a=>`- [${a.title}](${origin}/insights/${a.slug}.html) (${a.published}): ${a.summary}`),'']:[];}),
    '## Projects',
    ...projects.map(p=>`- [${p.title}](${origin}/case-studies/${p.slug}.html)${p.employer?' (portfolio with employer)':''}`),
    ''
  ].join('\n'));
}
console.log(`Built ${pages.length*2} static pages from shared components and English content. ${process.env.SITE_ORIGIN ? 'Release canonicals enabled.' : 'Preview pages are noindex; release origin is not set.'}`);

await writeFile(new URL('../site-i18n.js',import.meta.url),`/* Generated from content/th/site.mjs. */\n(()=>{const copy=new Map(${JSON.stringify([...thaiCopy])});const thai=document.documentElement.lang==='th';const translate=${translateThai.toString().replaceAll('thaiCopy','copy')};window.JPMI18n={thai,t:text=>thai?translate(text):text};})();\n`);
